#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int an = 0;

    while (true) {
        int count1 = 0;
        for (int x : a) if (x == 1) ++count1;
        if (count1 == 0) break;

        int idx = -1;
        for (int i = 0; i < (int)a.size(); ++i) {
            if (a[i] == 1) {
                idx = i;
                break;
            }
        }

        an = max(an, idx + count1);
        a.erase(a.begin() + idx);
    }

    cout << max(an, (int)a.size()) << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    int an = 0;

    auto count_ones = [&](const vector<int>& v) {
        return count(v.begin(), v.end(), 1);
    };

    while (count_ones(a) > 0) {
        int ones = count_ones(a);
        auto it = find(a.begin(), a.end(), 1);
        int idx = distance(a.begin(), it);
        an = max(idx + ones, an);
        a.erase(it);
    }

    cout << max(an, (int)a.size()) << '\n';
    return 0;
}

